function cheapestBasket(prices: number[], bundles: number[][], needs: number[]): number {
  const n = prices.length;
  const go = (list: number[]): number => {
    let best = 0;
    for (let i = 0; i < n; i++) best += list[i] * prices[i];
    for (const b of bundles) {
      const rest: number[] = [];
      let ok = true;
      for (let i = 0; i < n && ok; i++) {
        if (b[i] > list[i]) ok = false;
        else rest.push(list[i] - b[i]);
      }
      if (ok) best = Math.min(best, b[n] + go(rest));
    }
    return best;
  };
  return go(needs);
}

