function cheapestBasket(prices: number[], bundles: number[][], needs: number[]): number {
  const n = prices.length;
  // a bundle that is not cheaper than its contents can never improve the answer
  const useful = bundles.filter(b => {
    let single = 0;
    for (let i = 0; i < n; i++) single += b[i] * prices[i];
    return b[n] < single;
  });
  const memo = new Map<string, number>();
  const go = (list: number[]): number => {
    const key = list.join(",");
    const hit = memo.get(key);
    if (hit !== undefined) return hit;
    let best = 0;
    for (let i = 0; i < n; i++) best += list[i] * prices[i];
    for (const b of useful) {
      const rest = new Array<number>(n);
      let ok = true;
      for (let i = 0; i < n; i++) {
        rest[i] = list[i] - b[i];
        if (rest[i] < 0) { ok = false; break; }
      }
      if (ok) best = Math.min(best, b[n] + go(rest));
    }
    memo.set(key, best);
    return best;
  };
  return go(needs);
}

