class Solution:
    def cheapestBasket(self, prices: List[int], bundles: List[List[int]], needs: List[int]) -> int:
        n = len(prices)
        # a bundle that is not cheaper than its contents can never improve the answer
        useful = [b for b in bundles if b[n] < sum(b[i] * prices[i] for i in range(n))]

        @lru_cache(maxsize=None)
        def go(lst):
            best = sum(c * p for c, p in zip(lst, prices))
            for b in useful:
                rest = tuple(lst[i] - b[i] for i in range(n))
                if min(rest) >= 0:
                    best = min(best, b[n] + go(rest))
            return best

        return go(tuple(needs))

